The packet scheduler could attempt a reinjection after receiving an
MP_FAIL and before the infinite map has been transmitted, causing a
deadlock since MPTCP needs to do the reinjection atomically from WRT
fallback.

Address the issue explicitly avoiding the reinjection in the critical
scenario. Note that this is the only fallback critical section that
could potentially send packets and hit the double-lock.

Reported-by: Jakub Kicinski <kuba@kernel.org>
Closes: https://netdev-ctrl.bots.linux.dev/logs/vmksft/mptcp-dbg/results/412720/1-mptcp-join-sh/stderr
Fixes: f8a1d9b18c5e ("mptcp: make fallback action and fallback decision atomic")
Cc: stable@vger.kernel.org
Signed-off-by: Paolo Abeni <pabeni@redhat.com>
Reviewed-by: Matthieu Baerts (NGI0) <matttbe@kernel.org>
Signed-off-by: Matthieu Baerts (NGI0) <matttbe@kernel.org>
Link: https://patch.msgid.link/20251205-net-mptcp-misc-fixes-6-19-rc1-v1-4-9e4781a6c1b8@kernel.org
Signed-off-by: Jakub Kicinski <kuba@kernel.org>

Here is the root cause:
In `__mptcp_retrans`, the retransmission logic only checked `__mptcp_check_fallback(msk)` to skip retransmission during fallback. However, when an infinite fallback is in progress (i.e., `msk->allow_subflows` is false), the retransmission can still proceed and attempt to acquire the `fallback_lock` recursively or in a way that causes a deadlock with other lock acquisitions. The missing condition allows the retransmission to happen while subflows are permanently disallowed, leading to a recursive locking deadlock.

Here is the patch:

 static void __mptcp_retrans(struct sock *sk)
 {
 	struct mptcp_sendmsg_info info = { .data_lock_held = true, };
 	struct mptcp_sock *msk = mptcp_sk(sk);
 	struct mptcp_subflow_context *subflow;
 	struct mptcp_data_frag *dfrag;
 	struct sock *ssk;
 	int ret, err;
 	u16 len = 0;

 	mptcp_clean_una_wakeup(sk);

 	/* first check ssk: need to kick "stale" logic */
 	err = mptcp_sched_get_retrans(msk);
 	dfrag = mptcp_rtx_head(sk);
 	if (!dfrag) {
 		if (mptcp_data_fin_enabled(msk)) {
 			struct inet_connection_sock *icsk = inet_csk(sk);

 			WRITE_ONCE(icsk->icsk_retransmits,
 				   icsk->icsk_retransmits + 1);
 			mptcp_set_datafin_timeout(sk);
 			mptcp_send_ack(msk);

 			goto reset_timer;
 		}

 		if (!mptcp_send_head(sk))
 			goto clear_scheduled;

 		goto reset_timer;
 	}

 	if (err)
 		goto reset_timer;

 	mptcp_for_each_subflow(msk, subflow) {
 		if (READ_ONCE(subflow->scheduled)) {
 			u16 copied = 0;

 			mptcp_subflow_set_scheduled(subflow, false);

 			ssk = mptcp_subflow_tcp_sock(subflow);

 			lock_sock(ssk);

 			/* limit retransmission to the bytes already sent on some subflows */
 			info.sent = 0;
 			info.limit = READ_ONCE(msk->csum_enabled) ? dfrag->data_len :
 								    dfrag->already_sent;

 			/*
 			 * make the whole retrans decision, xmit, disallow
-			 * fallback atomic
+			 * fallback atomic, note that we can't retrans even
+			 * when an infinite fallback is in progress, i.e. new
+			 * subflows are disallowed.
 			 */
 			spin_lock_bh(&msk->fallback_lock);
-			if (__mptcp_check_fallback(msk)) {
+			if (__mptcp_check_fallback(msk) ||
+			    !msk->allow_subflows) {
 				spin_unlock_bh(&msk->fallback_lock);
 				release_sock(ssk);
 				goto clear_scheduled;
 			}

 			while (info.sent < info.limit) {
 				ret = mptcp_sendmsg_frag(sk, ssk, dfrag, &info);
 				if (ret <= 0)
 					break;

 				MPTCP_INC_STATS(sock_net(sk), MPTCP_MIB_RETRANSSEGS);
 				copied += ret;
 				info.sent += ret;
 			}
 			if (copied) {
 				len = max(copied, len);
 				tcp_push(ssk, 0, info.mss_now, tcp_sk(ssk)->nonagle,
 					 info.size_goal);
 				msk->allow_infinite_fallback = false;
 			}
 			spin_unlock_bh(&msk->fallback_lock);

 			release_sock(ssk);
 		}
 	}

 	msk->bytes_retrans += len;
 	dfrag->already_sent = max(dfrag->already_sent, len);

 reset_timer:
 	mptcp_check_and_set_pending(sk);

 	if (!mptcp_rtx_timer_pending(sk))
 		mptcp_reset_rtx_timer(sk);

 clear_scheduled:
 	/* If no rtx data was available or in case of fallback, there
 	 * could be left-over scheduled subflows; clear them all
 	 * or later xmit could use bad ones
 	 */
 	mptcp_for_each_subflow(msk, subflow)
 		if (READ_ONCE(subflow->scheduled))
 			mptcp_subflow_set_scheduled(subflow, false);
 }



